// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // Fuzzed params: caller address and a bool indicating whether the callee should revert.
    // The general rule: reference C allows any caller to invoke forward; the mutant reverts for non-owner callers.
    function testFuzz_property(address caller, bool calleeReverts) public {
        // avoid zero address for clarity (still wide)
        vm.assume(caller != address(0));

        // Deploy a helper callee that either reverts on receive or records the call
        RecorderCallee callee = new RecorderCallee(calleeReverts);

        // Fund caller so they can send tx value if needed (not needed here but safe)
        vm.deal(caller, 1 ether);

        // prepare calldata: we will call an arbitrary function on callee; C.forward just forwards bytes
        // Use an innocuous payload that the RecorderCallee understands (it has a function doSomething())
        bytes memory data = abi.encodeWithSelector(RecorderCallee.doSomething.selector, uint256(42));

        bool ok;
        // make the call as the fuzzed caller
        vm.prank(caller);
        try c.forward(address(callee), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees: any caller may call forward; whether it succeeds depends only on the callee behavior.
        // Our RecorderCallee will revert when calleeReverts==true; otherwise it returns normally.
        // Therefore for the correct contract: ok == !calleeReverts for ALL callers.
        // The mutant will additionally make ok==false whenever caller != owner even if calleeReverts==false.
        assertTrue(ok == (!calleeReverts));
    }
}

// Helper that either reverts on received calls or records the call and returns
contract RecorderCallee {
    bool public shouldRevert;
    uint256 public lastArg;
    uint256 public callCount;

    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }

    // A function matching the selector used by the test; records the argument and optionally reverts
    function doSomething(uint256 x) external returns (bool) {
        if (shouldRevert) revert("callee revert");
        lastArg = x;
        callCount += 1;
        return true;
    }

    // fallback to catch other encodings; behave similarly
    fallback() external payable {
        if (shouldRevert) revert("callee revert");
        callCount += 1;
    }

    receive() external payable {
        if (shouldRevert) revert("callee revert");
        callCount += 1;
    }
}
